#!/usr/bin/env node
// Remove Python bytecode generated by running CE skill scripts.
import { readdirSync, rmSync, statSync } from 'node:fs'
import { join } from 'node:path'

const walk = (dir) => {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name)
    if (name === '__pycache__') { rmSync(full, { recursive: true, force: true }); continue }
    const stat = statSync(full)
    if (stat.isDirectory()) walk(full)
    else if (name.endsWith('.pyc')) rmSync(full, { force: true })
  }
}
walk('skills')
